const cases=[
{id:'KYC-2418',name:'Horizon Pension Fund',type:'Institutional',risk:'Medium',owner:'R. Ncube',readiness:96,status:'Ready',blockers:0,next:'Final activation',age:'1.2d',stage:'approval',ubo:'Complete',screen:'Clear',tax:'Complete',suitability:'Passed',mandate:'Approved',evidence:'12 / 12',human:'Approved'},
{id:'KYC-2422',name:'Mupfumi Family Office',type:'Family office',risk:'High',owner:'T. Moyo',readiness:68,status:'Action',blockers:3,next:'Source of wealth evidence',age:'2.7d',stage:'aml',ubo:'Complete',screen:'PEP review',tax:'Complete',suitability:'Passed',mandate:'Draft',evidence:'8 / 11',human:'Pending'},
{id:'KYC-2427',name:'Baobab Endowment',type:'Institutional',risk:'Low',owner:'S. Dube',readiness:82,status:'Action',blockers:2,next:'Authorised signatory ID',age:'1.9d',stage:'identity',ubo:'Complete',screen:'Clear',tax:'Complete',suitability:'Passed',mandate:'Review',evidence:'9 / 11',human:'Pending'},
{id:'KYC-2431',name:'Nyanga Holdings',type:'Corporate',risk:'Medium',owner:'R. Ncube',readiness:54,status:'Action',blockers:4,next:'Ownership verification',age:'3.1d',stage:'ownership',ubo:'Incomplete',screen:'Not run',tax:'Pending',suitability:'Pending',mandate:'Not started',evidence:'5 / 10',human:'Pending'},
{id:'KYC-2436',name:'Savannah Charitable Trust',type:'Trust',risk:'High',owner:'L. Chari',readiness:71,status:'Action',blockers:3,next:'Enhanced due diligence',age:'4.1d',stage:'aml',ubo:'Complete',screen:'Adverse media review',tax:'Complete',suitability:'Passed',mandate:'Review',evidence:'8 / 12',human:'Pending'}
];
let caseId=cases[0].id, caseTab='overview';
function filteredCases(){const q=$('#v33CaseSearch')?.value.toLowerCase()||'',f=$('#v33CaseFilter')?.value||'action';return cases.filter(c=>(!q||`${c.name} ${c.id} ${c.owner}`.toLowerCase().includes(q))&&(f==='all'||f==='action'&&c.status!=='Active'&&c.status!=='Ready'||f==='ready'&&c.status==='Ready'||f==='high'&&c.risk==='High'))}
function renderCaseList(){const h=$('#v33CaseList');if(!h)return;h.innerHTML=filteredCases().map(c=>`<div class="v33-case ${c.id===caseId?'active':''}" data-case-id="${c.id}"><div class="v33-case-top"><span><strong>${esc(c.name)}</strong><small>${c.id} · ${c.type} · ${c.owner}</small></span><span class="v33-chip ${c.risk==='High'?'fail':c.status==='Ready'?'pass':'info'}">${c.status==='Ready'?'Ready':c.risk}</span></div><div class="v33-readiness"><div class="v33-progress ${c.readiness<70?'warn':''}"><i style="width:${c.readiness}%"></i></div><strong style="font-size:10px">${c.readiness}%</strong></div><small style="margin-top:7px">${c.blockers} blockers · next: ${esc(c.next)} · ${c.age}</small></div>`).join('')||'<div class="v33-empty">No cases match this view.</div>';$$('[data-case-id]',h).forEach(x=>x.onclick=()=>{caseId=x.dataset.caseId;caseTab='overview';renderCaseList();renderCaseDetail()})}
function caseStageTab(stage){return ({application:'overview',ownership:'parties',identity:'kyc',aml:'kyc',mandate:'suitability',approval:'approvals',active:'approvals'})[stage]||'overview'}
function renderCaseDetail(){const c=cases.find(x=>x.id===caseId)||cases[0],h=$('#v33CaseDetail');if(!h)return;const stages=[['Application','application'],['Ownership','ownership'],['Identity','identity'],['Financial crime','aml'],['Mandate','mandate'],['Approval','approval']];const order=['application','ownership','identity','aml','mandate','approval'],cur=Math.max(0,order.indexOf(c.stage));h.innerHTML=`<div class="v33-card-head"><div><div class="v33-kicker">${c.id} · ${c.type}</div><h2 style="font-size:18px">${esc(c.name)}</h2><p>${c.readiness}% ready · ${c.blockers} blockers · owner ${esc(c.owner)} · ${c.age}</p></div><span class="v33-chip ${c.status==='Ready'||c.status==='Active'?'pass':c.risk==='High'?'fail':'warn'}">${c.status}</span></div><div class="v33-card-body"><div class="v33-journey">${stages.map(([lab,key],i)=>`<button class="${i<cur?'done':i===cur?'active':c.blockers&&i===cur?'blocked':''}" data-v33-case-stage="${key}"><span>${String(i+1).padStart(2,'0')}</span><strong>${lab}</strong></button>`).join('')}</div><div class="v33-tabs" style="margin-top:12px"><button class="${caseTab==='overview'?'active':''}" data-v33-case-tab="overview">Overview</button><button class="${caseTab==='parties'?'active':''}" data-v33-case-tab="parties">Parties & ownership</button><button class="${caseTab==='kyc'?'active':''}" data-v33-case-tab="kyc">KYC / AML</button><button class="${caseTab==='suitability'?'active':''}" data-v33-case-tab="suitability">Suitability & mandate</button><button class="${caseTab==='evidence'?'active':''}" data-v33-case-tab="evidence">Evidence</button><button class="${caseTab==='approvals'?'active':''}" data-v33-case-tab="approvals">Approvals & audit</button></div><div id="v33CaseTabPane" style="margin-top:12px"></div></div>`;$$('[data-v33-case-tab]',h).forEach(b=>b.onclick=()=>{caseTab=b.dataset.v33CaseTab;renderCaseDetail()});$$('[data-v33-case-stage]',h).forEach(b=>b.onclick=()=>{caseTab=caseStageTab(b.dataset.v33CaseStage);renderCaseDetail()});renderCasePane(c)}
function renderCasePane(c){const h=$('#v33CaseTabPane');if(!h)return;if(caseTab==='overview'){h.innerHTML=`<div class="v33-grid"><article class="v33-card v33-span-7"><div class="v33-card-head"><div><div class="v33-kicker">DECISION BRIEF</div><h2>What must happen next</h2></div></div><div class="v33-card-body"><div class="v33-taskgrid"><div class="v33-task"><span>Next action</span><strong>${esc(c.next)}</strong><small>Assigned to ${esc(c.owner)}</small></div><div class="v33-task"><span>Readiness</span><strong>${c.readiness}%</strong><small>${c.blockers} hard blockers</small></div><div class="v33-task"><span>Financial crime</span><strong>${esc(c.screen)}</strong><small>Human disposition required for exceptions</small></div><div class="v33-task"><span>Mandate</span><strong>${esc(c.mandate)}</strong><small>Limits and dealing permissions</small></div></div></div></article><aside class="v33-card v33-span-5"><div class="v33-card-head"><div><div class="v33-kicker">CONTROL SUMMARY</div><h2>Activation gates</h2></div></div><div class="v33-card-body"><div class="v33-list"><div class="v33-row"><span><strong>Ownership</strong><small>UBOs and controllers</small></span><em>${c.ubo}</em></div><div class="v33-row"><span><strong>Evidence</strong><small>Required documents</small></span><em>${c.evidence}</em></div><div class="v33-row"><span><strong>Suitability</strong><small>Risk and appropriateness</small></span><em>${c.suitability}</em></div><div class="v33-row"><span><strong>Human KYC decision</strong><small>Compliance authority</small></span><em>${c.human}</em></div></div></div></aside></div>`}else if(caseTab==='parties'){h.innerHTML=`<div class="v33-grid"><article class="v33-card v33-span-7"><div class="v33-card-head"><div><div class="v33-kicker">LEGAL & BENEFICIAL OWNERSHIP</div><h2>Parties controlling the relationship</h2></div><button class="v33-btn" id="v33AddParty">+ Party</button></div><div class="v33-table-wrap"><table class="v33-table"><thead><tr><th>Party</th><th>Role</th><th>Ownership</th><th>ID</th><th>Screening</th></tr></thead><tbody><tr><td><strong>${esc(c.name)}</strong><small>Primary applicant</small></td><td>Legal entity</td><td>—</td><td>Verified</td><td>Clear</td></tr><tr><td><strong>Tariro Chuma</strong><small>ZW passport</small></td><td>Controller / signatory</td><td>35%</td><td>Verified</td><td>${c.risk==='High'?'Review':'Clear'}</td></tr><tr><td><strong>Munashe Trust Co.</strong></td><td>Beneficial owner</td><td>25%</td><td>Verified</td><td>Clear</td></tr></tbody></table></div></article><aside class="v33-card v33-span-5"><div class="v33-card-head"><div><div class="v33-kicker">OWNERSHIP CONTROL</div><h2>Completeness</h2></div></div><div class="v33-card-body"><div class="v33-list"><div class="v33-row"><span><strong>Ownership total</strong><small>Declared economic interest</small></span><em>100%</em></div><div class="v33-row"><span><strong>Controllers identified</strong><small>Board / authorised officials</small></span><em>${c.ubo==='Complete'?'Complete':'Review'}</em></div><div class="v33-row"><span><strong>Signatories verified</strong><small>Authority evidence</small></span><em>${c.readiness>75?'Complete':'Pending'}</em></div></div></div></aside></div>`}else if(caseTab==='kyc'){h.innerHTML=`<div class="v33-grid"><article class="v33-card v33-span-8"><div class="v33-card-head"><div><div class="v33-kicker">KYC / AML</div><h2>Identity and financial-crime controls</h2></div><button class="v33-btn" id="v33RefreshScreening">Refresh screening</button></div><div class="v33-card-body"><div class="v33-lane-grid"><div class="v33-lane"><span>Identity</span><strong>${c.readiness>60?'Verified':'Pending'}</strong><small>Document + liveness / entity registry</small></div><div class="v33-lane"><span>Sanctions</span><strong>${c.screen.includes('PEP')?'Clear':'Clear'}</strong><small>Current screening provider result</small></div><div class="v33-lane"><span>PEP</span><strong>${c.screen.includes('PEP')?'Review':'No match'}</strong><small>Human disposition if matched</small></div><div class="v33-lane"><span>Adverse information</span><strong>${c.screen.includes('Adverse')?'Review':'Clear'}</strong><small>Source links retained</small></div></div><div class="v33-form" style="margin-top:12px"><label class="v33-field"><span>Source of funds</span><textarea class="v33-textarea">Investment contributions / operating cashflows supported by bank evidence.</textarea></label><label class="v33-field"><span>Source of wealth</span><textarea class="v33-textarea">Audited earnings and investment proceeds. Supporting evidence retained.</textarea></label><label class="v33-field wide"><span>Human reviewer rationale</span><textarea class="v33-textarea" id="v33KycRationale" placeholder="Record why the evidence is sufficient or what remains unresolved."></textarea></label></div></div></article><aside class="v33-card v33-span-4"><div class="v33-card-head"><div><div class="v33-kicker">RISK RATING</div><h2>${c.risk} risk</h2></div></div><div class="v33-card-body"><div class="v33-list"><div class="v33-row"><span><strong>Jurisdiction</strong></span><em>Zimbabwe</em></div><div class="v33-row"><span><strong>Client type</strong></span><em>${c.type}</em></div><div class="v33-row"><span><strong>EDD</strong></span><em>${c.risk==='High'?'Required':'Not required'}</em></div></div></div></aside></div>`;$('#v33RefreshScreening')?.addEventListener('click',()=>{c.screen='Clear';toast('Screening refreshed','Current sanctions, PEP and adverse-information checks retained with evidence.');renderCaseDetail()})}else if(caseTab==='suitability'){h.innerHTML=`<div class="v33-grid"><article class="v33-card v33-span-7"><div class="v33-card-head"><div><div class="v33-kicker">SUITABILITY</div><h2>Investor profile and appropriateness</h2></div></div><div class="v33-card-body"><div class="v33-form"><label class="v33-field"><span>Investor classification</span><select class="v33-select"><option>Professional / institutional</option><option>Retail</option></select></label><label class="v33-field"><span>Risk profile</span><select class="v33-select"><option>Balanced growth</option><option>Conservative</option><option>Growth</option></select></label><label class="v33-field"><span>Investment horizon</span><select class="v33-select"><option>5+ years</option></select></label><label class="v33-field"><span>Liquidity need</span><select class="v33-select"><option>Quarterly or less</option></select></label><label class="v33-field"><span>Base currency</span><select class="v33-select"><option>USD</option><option>ZWG</option></select></label><label class="v33-field"><span>Offshore permission</span><select class="v33-select"><option>Permitted within mandate</option><option>Not permitted</option></select></label></div></div></article><aside class="v33-card v33-span-5"><div class="v33-card-head"><div><div class="v33-kicker">MANDATE</div><h2>Digitised constraints</h2></div></div><div class="v33-card-body"><div class="v33-list"><div class="v33-row"><span><strong>Single issuer</strong><small>Hard limit</small></span><em>10%</em></div><div class="v33-row"><span><strong>Equities</strong><small>Approved band</small></span><em>30–65%</em></div><div class="v33-row"><span><strong>Private assets</strong><small>Maximum</small></span><em>20%</em></div><div class="v33-row"><span><strong>Fees</strong><small>Signed fee schedule</small></span><em>${c.mandate}</em></div></div></div></aside></div>`}else if(caseTab==='evidence'){h.innerHTML=`<div class="v33-card"><div class="v33-card-head"><div><div class="v33-kicker">EVIDENCE</div><h2>${c.evidence} received</h2><p>Required evidence is versioned, classified and linked to the control it supports.</p></div><button class="v33-btn" id="v33RequestEvidence">Request evidence</button></div><div class="v33-table-wrap"><table class="v33-table"><thead><tr><th>Evidence</th><th>Control</th><th>Provided by</th><th>Verified by</th><th>State</th></tr></thead><tbody><tr><td>Certificate / trust deed</td><td>Legal existence</td><td>Applicant</td><td>R. Ncube</td><td><span class="v33-chip pass">Verified</span></td></tr><tr><td>Bank statement</td><td>Source of funds</td><td>Applicant</td><td>Compliance</td><td><span class="v33-chip ${c.blockers?'warn':'pass'}">${c.blockers?'Review':'Verified'}</span></td></tr><tr><td>Tax self-certification</td><td>FATCA / CRS</td><td>Applicant</td><td>Client Services</td><td><span class="v33-chip pass">Verified</span></td></tr></tbody></table></div></div>`;$('#v33RequestEvidence')?.addEventListener('click',()=>toast('Evidence request created','Secure request added to the applicant portal and case timeline.'))}else{h.innerHTML=`<div class="v33-grid"><article class="v33-card v33-span-7"><div class="v33-card-head"><div><div class="v33-kicker">HUMAN DECISION</div><h2>Compliance approval</h2><p>AI can summarise evidence but cannot approve or activate the relationship.</p></div></div><div class="v33-card-body"><label class="v33-field"><span>Decision rationale</span><textarea class="v33-textarea" id="v33DecisionRationale" placeholder="Record the human basis for approval, rejection or request for more evidence."></textarea></label><div style="display:flex;gap:8px;margin-top:10px"><button class="v33-btn" id="v33MoreEvidence">Request more evidence</button><button class="v33-btn primary" id="v33ApproveKyc">Approve KYC</button></div></div></article><aside class="v33-card v33-span-5"><div class="v33-card-head"><div><div class="v33-kicker">ACTIVATION</div><h2>${c.status==='Active'?'Client active':'Final controlled output'}</h2></div></div><div class="v33-card-body"><div class="v33-list"><div class="v33-row"><span><strong>KYC decision</strong></span><em>${c.human}</em></div><div class="v33-row"><span><strong>Evidence complete</strong></span><em>${c.blockers===0?'Yes':'No'}</em></div><div class="v33-row"><span><strong>Mandate approved</strong></span><em>${c.mandate}</em></div></div><button class="v33-btn primary" id="v33ActivateClient" style="width:100%;margin-top:12px" ${c.status==='Active'?'disabled':''}>${c.status==='Active'?'Active':'Activate client'}</button></div></aside></div>`;$('#v33MoreEvidence')?.addEventListener('click',()=>{c.status='Action';c.blockers=Math.max(1,c.blockers);toast('Case returned','Evidence request added to applicant portal.')});$('#v33ApproveKyc')?.addEventListener('click',()=>{const r=$('#v33DecisionRationale')?.value.trim();if(!r&&c.human!=='Approved')return toast('Rationale required','Record a human decision rationale before approval.','error');c.human='Approved';if(c.blockers===0)c.status='Ready';c.stage='approval';toast('KYC approved','Human decision retained with reviewer identity and evidence snapshot.');renderCaseList();renderCaseDetail()});$('#v33ActivateClient')?.addEventListener('click',()=>{if(c.human!=='Approved'||c.blockers!==0||c.mandate!=='Approved')return toast('Activation blocked','KYC approval, complete evidence and approved mandate are all required.','error');c.status='Active';c.stage='active';c.readiness=100;toast('Client activated',`${c.name} is now active with governed client master and mandate.`);renderCaseList();renderCaseDetail()})}}
