function renderModels(){const q=$('#v33ModelSearch')?.value.toLowerCase()||'',h=$('#v33ModelRows');if(h)h.innerHTML=models.filter(m=>!q||m.join(' ').toLowerCase().includes(q)).map(m=>`<tr class="clickable"><td><strong>${m[1]}</strong><small>${m[0]}</small></td><td>${m[2]}</td><td>${m[3]}</td><td>${m[4]}</td><td>${m[5]}</td><td><span class="v33-chip ${m[6]==='Production'?'pass':'warn'}">${m[6]}</span></td></tr>`).join('');renderModelBuild()}
function renderModelBuild(){const h=$('#v33ModelBuild');if(!h)return;$$('[data-model-step]').forEach(b=>b.classList.toggle('active',b.dataset.modelStep===modelStep));if(modelStep==='definition')h.innerHTML=`<div class="v33-form"><label class="v33-field wide"><span>Model name</span><input class="v33-input" id="v33ModelName" placeholder="Specific model name"></label><label class="v33-field"><span>Model class</span><select class="v33-select"><option>Risk</option><option>Valuation</option><option>Optimisation</option><option>Execution / TCA</option><option>AI / ML</option></select></label><label class="v33-field"><span>Human owner</span><select class="v33-select"><option>Risk Analytics</option><option>Quant Research</option><option>Valuation</option></select></label><label class="v33-field wide"><span>Purpose and permitted use</span><textarea class="v33-textarea" id="v33ModelPurpose" placeholder="What decision/output may this model influence, and what is explicitly prohibited?"></textarea></label></div>`;else if(modelStep==='data')h.innerHTML=`<div class="v33-form"><label class="v33-field"><span>Governed dataset</span><select class="v33-select"><option>Whole Portfolio Positions</option><option>Official Performance</option><option>Market History</option></select></label><label class="v33-field"><span>Snapshot version</span><input class="v33-input" value="2026-08-31T15:30Z"></label><label class="v33-field wide"><span>Feature / field specification</span><textarea class="v33-textarea">Security ID, market value, factor exposures, price history, liquidity score…</textarea></label></div>`;else if(modelStep==='method')h.innerHTML=`<div class="v33-form"><label class="v33-field wide"><span>Methodology</span><textarea class="v33-textarea" style="min-height:130px" placeholder="Formula, algorithm, architecture, calibration method and assumptions."></textarea></label><label class="v33-field"><span>Code / notebook version</span><input class="v33-input" value="git:quant/models@d9a84f1"></label><label class="v33-field"><span>Key assumptions</span><input class="v33-input" placeholder="Distribution, liquidity, regime…"></label></div>`;else if(modelStep==='testing')h.innerHTML=`<div class="v33-list"><div class="v33-row"><span><strong>Unit / integration tests</strong><small>Expected numeric and boundary behaviour</small></span><em>Required</em></div><div class="v33-row"><span><strong>Backtest</strong><small>Historical performance and failures</small></span><em>Required</em></div><div class="v33-row"><span><strong>Stress / sensitivity</strong><small>Parameter and regime response</small></span><em>Required</em></div><div class="v33-row"><span><strong>Challenger comparison</strong><small>Alternative method or benchmark</small></span><em>Required</em></div></div>`;else h.innerHTML=`<div class="v33-list"><div class="v33-row"><span><strong>Independent validator</strong><small>Cannot be model developer</small></span><em>Unassigned</em></div><div class="v33-row"><span><strong>Validation findings</strong><small>Severity, remediation and closure</small></span><em>Pending</em></div><div class="v33-row"><span><strong>Model committee</strong><small>Approval of use and limitations</small></span><em>Pending</em></div><div class="v33-row"><span><strong>Production deployment</strong><small>Versioned, monitored, rollback-ready</small></span><em>Blocked</em></div></div>`}
function initModels(){$$('[data-model-step]').forEach(b=>b.onclick=()=>{modelStep=b.dataset.modelStep;renderModelBuild()});$('#v33ModelSearch')?.addEventListener('input',renderModels);$('#v33ModelNew')?.addEventListener('click',()=>{modelStep='definition';renderModelBuild();$('#v33ModelName')?.focus()});$('#v33ModelCalendar')?.addEventListener('click',()=>toast('Validation calendar','Upcoming independent validations and expiry dates available.'));renderModels()}

/* ---------------- CONSTRUCTION ---------------- */
let buildTab='targets',optimised=false;const targets=[['Zimbabwe equities',32.4,34],['USD equities',14.8,16],['Fixed income',28.8,26],['Private assets',10.2,10],['Cash & money market',13.8,14]];
function targetTotal(){return targets.reduce((a,x)=>a+x[2],0)}
function renderConstruction(){const h=$('#v33ConstructionView');if(!h)return;$$('[data-v33-build-tab]').forEach(b=>b.classList.toggle('active',b.dataset.v33BuildTab===buildTab));if(buildTab==='targets'){h.innerHTML=`<div class="v33-grid"><article class="v33-card v33-span-8"><div class="v33-card-head"><div><div class="v33-kicker">TARGET PORTFOLIO</div><h2>Current → proposed allocation</h2><p>Adjust targets; total must equal 100% before optimisation.</p></div><span class="v33-chip ${Math.abs(targetTotal()-100)<.1?'pass':'warn'}" id="v33TargetTotal">${targetTotal().toFixed(1)}%</span></div><div class="v33-card-body">${targets.map((t,i)=>`<div class="v33-weight-row"><strong>${t[0]}</strong><div class="v33-progress"><i style="width:${t[1]*2}%"></i></div><span>${t[1]}%</span><input type="range" min="0" max="50" step=".5" value="${t[2]}" data-target-i="${i}"><strong data-target-label="${i}">${t[2]}%</strong></div>`).join('')}</div></article><aside class="v33-card v33-span-4"><div class="v33-card-head"><div><div class="v33-kicker">INVESTMENT INPUTS</div><h2>Views feeding the target</h2></div></div><div class="v33-card-body"><div class="v33-list"><div class="v33-row"><span><strong>Research alpha views</strong><small>8 current · 2 stale</small></span><em>Review</em></div><div class="v33-row"><span><strong>Risk model</strong><small>MOD-RISK-01 v3.8</small></span><em>Current</em></div><div class="v33-row"><span><strong>Transaction costs</strong><small>ZSE / VFEX / OTC curves</small></span><em>Current</em></div><div class="v33-row"><span><strong>Mandate constraints</strong><small>Effective-dated client rules</small></span><em>Enforced</em></div></div></div></aside></div>`;$$('[data-target-i]',h).forEach(inp=>inp.oninput=()=>{targets[+inp.dataset.targetI][2]=Number(inp.value);$(`[data-target-label="${inp.dataset.targetI}"]`,h).textContent=Number(inp.value).toFixed(1)+'%';const e=$('#v33TargetTotal');e.textContent=targetTotal().toFixed(1)+'%';e.className='v33-chip '+(Math.abs(targetTotal()-100)<.1?'pass':'warn')})}else if(buildTab==='constraints'){h.innerHTML=`<div class="v33-grid"><article class="v33-card v33-span-7"><div class="v33-card-head"><div><div class="v33-kicker">HARD CONSTRAINTS</div><h2>Mandate and risk rules</h2></div></div><div class="v33-card-body"><div class="v33-form"><label class="v33-field"><span>Single issuer maximum</span><input class="v33-input" type="number" value="10"></label><label class="v33-field"><span>Tracking error maximum</span><input class="v33-input" type="number" value="6.0"></label><label class="v33-field"><span>Liquidity cover minimum</span><input class="v33-input" type="number" value="1.25"></label><label class="v33-field"><span>Maximum turnover</span><input class="v33-input" type="number" value="10"></label><label class="v33-field"><span>Cash minimum</span><input class="v33-input" type="number" value="5"></label><label class="v33-field"><span>Private asset maximum</span><input class="v33-input" type="number" value="20"></label></div></div></article><aside class="v33-card v33-span-5"><div class="v33-card-head"><div><div class="v33-kicker">SOFT OBJECTIVES</div><h2>Optimisation preferences</h2></div></div><div class="v33-card-body"><div class="v33-list"><div class="v33-row"><span><strong>Maximise expected return</strong></span><em>Primary</em></div><div class="v33-row"><span><strong>Minimise transaction cost</strong></span><em>Secondary</em></div><div class="v33-row"><span><strong>Prefer liquid implementation</strong></span><em>Secondary</em></div></div></div></aside></div>`}else if(buildTab==='scenarios'){h.innerHTML=`<div class="v33-grid"><article class="v33-card v33-span-8"><div class="v33-card-head"><div><div class="v33-kicker">SCENARIO COMPARISON</div><h2>Portfolio consequences</h2></div></div><div class="v33-table-wrap"><table class="v33-table"><thead><tr><th>Scenario</th><th>Return</th><th>Tracking error</th><th>VaR</th><th>Liquidity</th><th>Turnover</th><th>Cost</th></tr></thead><tbody><tr><td><strong>Current</strong></td><td>12.84%</td><td>4.35%</td><td>2.18%</td><td>1.84×</td><td>—</td><td>—</td></tr><tr><td><strong>Proposed</strong></td><td>13.60%</td><td>4.80%</td><td>2.26%</td><td>1.72×</td><td>8.4%</td><td>19 bps</td></tr><tr><td><strong>Liquidity-first</strong></td><td>13.12%</td><td>4.44%</td><td>2.12%</td><td>2.06×</td><td>6.8%</td><td>15 bps</td></tr></tbody></table></div></article><aside class="v33-card v33-span-4"><div class="v33-card-head"><div><div class="v33-kicker">STRESS CHECK</div><h2>Proposed portfolio</h2></div></div><div class="v33-card-body"><div class="v33-list"><div class="v33-row"><span><strong>Equity −15%</strong></span><em>−5.8%</em></div><div class="v33-row"><span><strong>Rates +200 bps</strong></span><em>−1.9%</em></div><div class="v33-row"><span><strong>Liquidity stress</strong></span><em>1.38× cover</em></div></div></div></aside></div>`}else{h.innerHTML=`<div class="v33-grid"><article class="v33-card v33-span-9"><div class="v33-card-head"><div><div class="v33-kicker">IMPLEMENTATION ORDERS</div><h2>Trades generated by approved target</h2><p>These are drafts until promoted; OMS controls run again before approval.</p></div><button class="v33-btn primary" id="v33PromoteOrders" ${optimised?'':'disabled'}>Promote to Orders</button></div><div class="v33-table-wrap"><table class="v33-table"><thead><tr><th>Security</th><th>Side</th><th>Current weight</th><th>Target</th><th>Trade</th><th>Liquidity</th><th>Reason</th></tr></thead><tbody><tr><td>DLTA.ZW</td><td>Buy</td><td>8.8%</td><td>9.6%</td><td>ZWG 2.47m</td><td>2.1d</td><td>Research alpha</td></tr><tr><td>INN.VX</td><td>Buy</td><td>5.1%</td><td>6.4%</td><td>US$ 148k</td><td>1.4d</td><td>Research alpha</td></tr><tr><td>T-BILL-91D</td><td>Sell</td><td>13.7%</td><td>11.2%</td><td>US$ 530k</td><td>Same day</td><td>Fund target</td></tr></tbody></table></div></article><aside class="v33-card v33-span-3"><div class="v33-card-head"><div><div class="v33-kicker">PROMOTION GATES</div><h2>Before OMS</h2></div></div><div class="v33-card-body"><div class="v33-list"><div class="v33-row"><span><strong>Weights</strong></span><em>${Math.abs(targetTotal()-100)<.1?'Pass':'Fail'}</em></div><div class="v33-row"><span><strong>Optimiser</strong></span><em>${optimised?'Run complete':'Required'}</em></div><div class="v33-row"><span><strong>PM approval</strong></span><em>${optimised?'Ready':'Blocked'}</em></div></div></div></aside></div>`;$('#v33PromoteOrders')?.addEventListener('click',()=>{toast('Scenario promoted','Controlled OMS drafts created from the optimised target.');go('orders')})}}
function initConstruction(){$$('[data-v33-build-tab]').forEach(b=>b.onclick=()=>{buildTab=b.dataset.v33BuildTab;renderConstruction()});$('#v33Optimise')?.addEventListener('click',()=>{if(Math.abs(targetTotal()-100)>.1)return toast('Optimisation blocked',`Target weights total ${targetTotal().toFixed(1)}%, not 100%.`,'error');optimised=true;toast('Optimisation complete','Risk, liquidity, cost and mandate constraints evaluated.');buildTab='scenarios';renderConstruction()});$('#v33ConstructionSave')?.addEventListener('click',()=>toast('Scenario saved','Target weights, assumptions and model versions retained.'));renderConstruction()}

function init(){document.documentElement.dataset.release='v33';initOrders();initOnboarding();initRecon();initOps();initReports();initDocs();initFinancing();initNav();initReg();initData();initModels();initConstruction();bindGo();console.info('Matanho Nexus V33 true workspace rebuild ready')}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,550));else setTimeout(init,550);
